-- ENG-090 / ORG-069: rollback-only gate, authorization, scoring and audit proofs.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
\ir ../support/registration-fixtures.psql
\ir ../support/profile-complete-fixtures.psql
\ir ../support/abstract-fixtures.psql
\ir ../support/abstract-screening-fixtures.psql
\ir ../support/abstract-scoring-vectors.psql

select is((select count(*) from msrc_abstracts.screening_settings),0::bigint,'No active bands, similarity threshold or oral capacity seeded');
select ok(not exists(select 1 from pg_class c where c.relnamespace='msrc_abstracts'::regnamespace and c.relkind='r' and not(c.relrowsecurity and c.relforcerowsecurity)),'Every private table forces RLS');
select ok(not exists(select 1 from pg_policies where schemaname='msrc_abstracts'),'No client table policy');
select ok(not has_schema_privilege('authenticated','msrc_abstracts','USAGE'),'Participants have no private schema access');
select ok(not has_function_privilege('anon','public.msrc_staff_research_confirm_screening(text,uuid,integer,integer,uuid,jsonb)','EXECUTE'),'Anonymous cannot call screening RPC');
select ok(not has_function_privilege('service_role','public.msrc_staff_research_confirm_screening(text,uuid,integer,integer,uuid,jsonb)','EXECUTE'),'No service-role staff bypass');
select ok(msrc_abstracts.review_settings_ready_2027(pg_temp.screening_configuration()||'{"acceptanceThreshold":null,"keywordCount":null,"correspondingAuthorPolicy":null,"ongoingPolicy":null}'::jsonb),'Human scoring readiness does not activate or depend on legacy acceptance/keyword/ongoing settings');
select is((msrc_abstracts.screening_automatic(jsonb_set(pg_temp.abstract_document(),'{body}',jsonb_build_object('background',repeat('word ',339),'objectives','a','methods','b','results','c','limitations','d','conclusion','e')))->0->>'passed'),'true','350 including six headings passes G1');
select is((msrc_abstracts.screening_automatic(jsonb_set(pg_temp.abstract_document(),'{body}',jsonb_build_object('background',repeat('word ',340),'objectives','a','methods','b','results','c','limitations','d','conclusion','e')))->0->>'passed'),'false','351 including headings fails G1');
select is((msrc_abstracts.screening_automatic(pg_temp.abstract_document()||jsonb_build_object('title',repeat('word ',20)))->3->>'passed'),'true','20 title words passes G4');
select is((msrc_abstracts.screening_automatic(pg_temp.abstract_document()||jsonb_build_object('title',repeat('word ',21)))->3->>'passed'),'false','21 title words fails G4');
select is((msrc_abstracts.screening_automatic(jsonb_set(pg_temp.abstract_document(),'{body,limitations}','"..."'::jsonb))->1->>'passed'),'false','Punctuation-only section fails G2');
select is((msrc_abstracts.screening_automatic(jsonb_set(pg_temp.abstract_document(),'{body,results}','""'::jsonb))->2->>'passed'),'false','Missing result fails G3');
select is((msrc_abstracts.screening_automatic(jsonb_set(pg_temp.abstract_document(),'{supervisor,email}','""'::jsonb))->3->>'passed'),'false','Missing supervisor email fails G4');
select is((msrc_abstracts.screening_automatic(jsonb_set(pg_temp.abstract_document(),'{ethics}',jsonb_build_object('status','approved','committee','','reference','','explanation','')))->4->>'passed'),'false','Approved ethics needs committee and reference');
select is((msrc_abstracts.screening_automatic(jsonb_set(pg_temp.abstract_document(),'{registration}',jsonb_build_object('status','registered','registry','','number','')))->4->>'passed'),'false','Registration completeness is independent of ethics');
select is((select sum((r->>'weight')::numeric) from jsonb_array_elements(msrc_abstracts.rubric_2027()) r),100::numeric,'Owner weights sum to 100');
select is(msrc_abstracts.weighted_total_2027(scores),total,'SQL/TS shared parity vector '||name) from pg_temp.abstract_scoring_vectors();
select is(msrc_abstracts.weighted_total_2027(jsonb_set(pg_temp.owner_scorecard(3)->'scores','{0,value}','2.5'::jsonb)),null::numeric,'Noninteger criterion scores rejected');
select is(msrc_abstracts.weighted_total_2027('[]'::jsonb),null::numeric,'Missing criteria never count as zero');
select is(msrc_abstracts.provisional_band(100,jsonb_build_array(pg_temp.owner_scorecard(4),pg_temp.owner_scorecard(4)),null), 'settings_unset','Suggested bands inactive without saved settings');
create function pg_temp.bands() returns jsonb language sql immutable as $$select '{"oralMin":85,"posterMin":60,"borderlineMin":55,"acceptanceMin":55}'::jsonb$$;
select is(msrc_abstracts.provisional_band(score,jsonb_build_array(pg_temp.owner_scorecard(4),pg_temp.owner_scorecard(4)),pg_temp.bands()),band,'Band boundary '||score) from (values(84.99::numeric,'poster'),(85,'oral_candidate'),(59.99,'borderline'),(60,'poster'),(54.99,'reject'),(55,'borderline')) v(score,band);
select is(msrc_abstracts.provisional_band(99,jsonb_build_array(pg_temp.owner_scorecard(4),jsonb_set(pg_temp.owner_scorecard(4),'{scores,2,value}','2'::jsonb)),pg_temp.bands()),'poster','Every reviewer Methodology must be at least 3 for oral');
select is(msrc_abstracts.provisional_band(99,jsonb_build_array(pg_temp.owner_scorecard(4),jsonb_set(pg_temp.owner_scorecard(4),'{scores,3,value}','2'::jsonb)),pg_temp.bands()),'poster','Every reviewer Results must be at least 3 for oral');
select is(msrc_abstracts.provisional_band(99,jsonb_build_array(pg_temp.owner_scorecard(4),pg_temp.owner_scorecard(4)),pg_temp.bands(),false),'poster','Oral-quality beyond capacity recommends poster');
select is(msrc_abstracts.similarity_score('unique scientific sample','unique scientific sample'),100::numeric,'Identical text is 100% internally similar');
select is(msrc_abstracts.shingle_similarity('A, b; C!','a b c'),100::numeric,'Fallback normalization ignores case and punctuation');
select is(round(msrc_abstracts.shingle_similarity('a b c d','a b c e'),2),33.33::numeric,'Fallback uses intersection over union of normalized three-token shingles');
select is(msrc_abstracts.shingle_similarity('...',''),0::numeric,'Empty normalized fallback text never invents similarity');

update msrc_staff.policy set enabled=true,email_daily_limit=1000;
update msrc_participant.policy set enabled=true,privacy_version='synthetic-registration-notice',email_daily_limit=1000;
update msrc_participant.retention_policy set enabled=true;
insert into msrc_authorization.edition_config(edition_key) values('synthetic-screening');
select pg_temp.registration_staff_fixture(9500,'synthetic-screening');
select pg_temp.registration_staff_fixture(9501,'synthetic-screening','scientificAdministrator');
select pg_temp.registration_staff_fixture(9502,'synthetic-screening','abstractReviewer');
select pg_temp.registration_staff_fixture(9503,'synthetic-screening','abstractReviewer');
select pg_temp.registration_fixture(9504,'synthetic-screening');
select pg_temp.complete_profile(9504,'synthetic-screening');
update msrc_participant.profile_details set student_status='year_6' where edition_key='synthetic-screening';
select pg_temp.abstract_claims(9500);
select is(public.msrc_staff_research_save_settings('synthetic-screening',0,pg_temp.screening_configuration()||'{"reviewDeadline":null,"acceptanceThreshold":null}'::jsonb)->>'state','ready','Approved rubric configured through incumbent settings without activating bands or supplying an old threshold');
select is(public.msrc_staff_research_save_settings('synthetic-screening',1,pg_temp.abstract_settings())->>'state','invalid','Staff cannot replace fixed owner rubric');
update msrc_abstracts.settings set enabled=true,evidence_ready=true where edition_key='synthetic-screening';
update msrc_participant.profile_details set specialty_interests=array['synthetic-specialty'] where edition_key='synthetic-screening';
create temporary table screening_result(key text primary key,value jsonb);
insert into screening_result values('draft',public.msrc_abstracts_save_draft('synthetic-screening',pg_temp.registration_claims(9504),null,0,pg_temp.abstract_document(),gen_random_uuid()));
create function pg_temp.screening_id() returns uuid language sql stable as $$select (value->'submission'->>'id')::uuid from screening_result where key='draft'$$;
select is(public.msrc_abstracts_finalize('synthetic-screening',pg_temp.registration_claims(9504),pg_temp.screening_id(),1,gen_random_uuid())->>'state','finalized','Real finalized snapshot created for gates');
select pg_temp.abstract_claims(9501);
select is(public.msrc_staff_research_save_settings('synthetic-screening',1,pg_temp.screening_configuration()||'{"acceptanceThreshold":null}'::jsonb)->>'state','ready','Staff explicitly finish review configuration after finalization without rewriting the snapshot');
select is(public.msrc_staff_research_prepare_packet('synthetic-screening',pg_temp.screening_id(),1,pg_temp.abstract_packet(),true)->>'state','prepared','Incumbent sanitation required');
select is(public.msrc_staff_research_confirm_screening('synthetic-screening',pg_temp.screening_id(),1,0,'e7900000-0000-4000-8000-000000009501',pg_temp.screening_input())->>'state','updated','Staff can record a pending screening');
select is((select status from msrc_abstracts.screenings limit 1),'pending','Threshold unset prevents pass');
select ok(not msrc_abstracts.screening_current(pg_temp.screening_id()),'Unconfigured similarity closes scoring');
select is(public.msrc_staff_research_assign('synthetic-screening',pg_temp.screening_id(),pg_temp.registration_actor(9502))->>'state','screening_required','Unscreened abstract cannot be assigned for scoring');
select is(public.msrc_staff_research_save_screening_settings('synthetic-screening',0,pg_temp.bands(),100,null)->>'state','denied','Scientific Administrator cannot save threshold/bands');
select pg_temp.abstract_claims(9502);
select is(public.msrc_staff_research_confirm_screening('synthetic-screening',pg_temp.screening_id(),1,1,gen_random_uuid(),pg_temp.screening_input())->>'state','denied','Reviewer cannot confirm screening');
select pg_temp.abstract_claims(9504);
select is(public.msrc_staff_research_submission('synthetic-screening',pg_temp.screening_id())->>'state','denied','Participant cannot read screening details');
select is(public.msrc_staff_research_confirm_screening('synthetic-screening',pg_temp.screening_id(),1,1,gen_random_uuid(),pg_temp.screening_input())->>'state','denied','Participant cannot confirm screening');
select pg_temp.abstract_claims(9500);
select is(public.msrc_staff_research_save_screening_settings('synthetic-screening',0,pg_temp.bands(),100,null)->>'state','ready','Super Admin explicitly saves provisional bands and threshold');
select is(public.msrc_staff_research_confirm_screening('synthetic-screening',pg_temp.screening_id(),1,1,'e7900000-0000-4000-8000-000000009502',pg_temp.screening_input())->>'state','updated','Super Admin may confirm all seven gates');
select is((select count(*) from msrc_abstracts.screening_gates),14::bigint,'Both rounds retain seven immutable gate rows');
select ok(msrc_abstracts.screening_current(pg_temp.screening_id()),'All seven gates confirmed and current');
select is(public.msrc_staff_research_confirm_screening('synthetic-screening',pg_temp.screening_id(),1,1,'e7900000-0000-4000-8000-000000009502',pg_temp.screening_input())->>'state','updated','Lost-success retry is idempotent');
select is((select count(*) from msrc_abstracts.screenings),2::bigint,'Idempotency creates no second screening event');
select is(public.msrc_staff_research_confirm_screening('synthetic-screening',pg_temp.screening_id(),1,1,gen_random_uuid(),pg_temp.screening_input())->>'state','conflict','Concurrent stale confirmation loses CAS without extra rows');
select ok(exists(select 1 from msrc_abstracts.audit where event='screening.passed'),'Passed event available to future notification PR without sending');
select is(public.msrc_staff_research_confirm_screening('synthetic-screening',pg_temp.screening_id(),1,2,gen_random_uuid(),pg_temp.screening_input()||'{"externalChecked":false,"externalReference":""}'::jsonb)->>'state','updated','External report may remain unchecked without fabricating evidence');
select ok(not msrc_abstracts.screening_current(pg_temp.screening_id()),'Threshold alone cannot pass G7 without external report attestation');
select is(pg_temp.confirm_screening(pg_temp.screening_id()),'updated','Separate external-report attestation can restore confirmed screening');
select is((select count(*) from msrc_outbox.messages where template_key='abstract_decision'),0::bigint,'Screening queues no participant communication');
select throws_ok($$update msrc_abstracts.screening_gates set passed=false$$,'55000',null,'Gate outcomes immutable');
select throws_ok($$delete from msrc_abstracts.screenings$$,'55000',null,'Screening events immutable');
select throws_ok($$truncate msrc_abstracts.screening_settings$$,'55000',null,'Settings history cannot be truncated');
select pg_temp.abstract_claims(9502);
select public.msrc_staff_research_declare_affiliations('synthetic-screening',array['Independent one']);
select pg_temp.abstract_claims(9503);
select public.msrc_staff_research_declare_affiliations('synthetic-screening',array['Independent two']);
select pg_temp.abstract_claims(9501);
select is(public.msrc_staff_research_auto_assign('synthetic-screening',pg_temp.screening_id())->>'count','2','Existing model assigns two independent reviewers');
select ok((select bool_and(rubric_version=2) from msrc_abstracts.assignments where submission_id=pg_temp.screening_id()),'Assignments freeze their explicitly approved review configuration version');
select is((select settings_version from msrc_abstracts.snapshots where submission_id=pg_temp.screening_id()),1,'Finalized snapshot retains its original submission-settings version');
select pg_temp.abstract_claims(9502);
select ok(public.msrc_staff_research_packet('synthetic-screening',(select id from msrc_abstracts.assignments where reviewer_id=pg_temp.registration_actor(9502)))::text !~ 'Canary|Supervisor|example.invalid|authors|affiliations|screening|externalReference','Blinded packet excludes identity, supervisor and private screening');
select is(public.msrc_staff_research_scorecard('synthetic-screening',(select id from msrc_abstracts.assignments where reviewer_id=pg_temp.registration_actor(9502)),1,jsonb_set(pg_temp.owner_scorecard(3),'{scores,0,value}','2.5'::jsonb),true)->>'state','invalid','Reviewer RPC refuses fractional scores before recording a card');
select is(public.msrc_staff_research_scorecard('synthetic-screening',(select id from msrc_abstracts.assignments where reviewer_id=pg_temp.registration_actor(9502)),1,pg_temp.owner_scorecard(4),true)->>'state','updated','First independent owner rubric scorecard');
select pg_temp.abstract_claims(9503);
select is(public.msrc_staff_research_scorecard('synthetic-screening',(select id from msrc_abstracts.assignments where reviewer_id=pg_temp.registration_actor(9503)),1,pg_temp.owner_scorecard(3),true)->>'state','updated','Second independent owner rubric scorecard');
select is((msrc_abstracts.review_summary(pg_temp.screening_id())->>'meanScore')::numeric,83.335::numeric,'Mean uses complete reviewer totals, never missing as zero');
select ok((select bool_and(scoring_rule='msrc2027_org069') from msrc_abstracts.scorecard_versions),'Every new immutable human card retains its approved scoring-rule version');
select throws_ok($$update msrc_abstracts.scorecard_versions set scoring_rule=null$$,'55000',null,'Human scorecard rule provenance cannot be rewritten');
select pg_temp.abstract_claims(9501);
insert into screening_result values('decision',public.msrc_staff_research_decision('synthetic-screening',pg_temp.screening_id(),1,'accept','Synthetic committee decision','Synthetic instructions',null));
select is((select value->>'state' from screening_result where key='decision'),'prepared','Human records actual decision separately');
select is(public.msrc_staff_research_request_review('synthetic-screening',pg_temp.screening_id(),2,3,'Synthetic borderline disagreement requires another reviewer',gen_random_uuid())->>'state','updated','Authorized staff route additional review through existing assignments');
select is((msrc_abstracts.review_summary(pg_temp.screening_id())->>'requiredReviews')::integer,3,'Explicit additional-review request raises current quorum');
select ok(not msrc_abstracts.reviews_complete(pg_temp.screening_id(),1),'Two cards no longer complete explicitly requested additional review');
select throws_ok($$update msrc_abstracts.additional_reviews set note='tampered'$$,'55000',null,'Additional review rationale is immutable');
select is(public.msrc_staff_research_confirm_screening('synthetic-screening',pg_temp.screening_id(),1,4,gen_random_uuid(),pg_temp.screening_input()||'{"investigation":true,"investigationNote":"Synthetic integrity concern"}'::jsonb)->>'state','updated','Investigation recorded independently of gates');
select is(public.msrc_staff_research_decision('synthetic-screening',pg_temp.screening_id(),1,'accept','Synthetic rationale','Instructions',null)->>'state','investigation_open','Open investigation blocks final human decision');
select is(public.msrc_staff_research_batch('synthetic-screening',array[(select (value->>'decisionId')::uuid from screening_result where key='decision')],gen_random_uuid(),'prepare')->>'state','investigation_open','Existing prepared decision cannot bypass investigation at batch preview');
select is(public.msrc_staff_research_confirm_screening('synthetic-screening',pg_temp.screening_id(),1,5,gen_random_uuid(),pg_temp.screening_input())->>'state','invalid','Investigation resolution needs a note');
select is(public.msrc_staff_research_confirm_screening('synthetic-screening',pg_temp.screening_id(),1,5,gen_random_uuid(),pg_temp.screening_input()||'{"investigationNote":"Synthetic concern resolved"}'::jsonb)->>'state','updated','Resolution appends history');
select is(public.msrc_staff_research_confirm_screening('synthetic-screening',pg_temp.screening_id(),1,6,gen_random_uuid(),pg_temp.screening_input()||'{"relevance":{"passed":false,"note":"Synthetic non-relevant work"},"failureDisposition":"final","note":"Mandatory non-correctable failure"}'::jsonb)->>'state','updated','Human classifies non-correctable mandatory failure');
select is((msrc_abstracts.screening_projection(pg_temp.screening_id())->>'status'),'failed_final','Non-correctable failure is rejection eligible');
select is(public.msrc_staff_research_decision('synthetic-screening',pg_temp.screening_id(),1,'reject','Mandatory eligibility failure','Synthetic instructions',null)->>'state','prepared','Human may reject mandatory failed screening without scientific scores');
select is(public.msrc_staff_research_decision('synthetic-screening',pg_temp.screening_id(),1,'accept','Cannot bypass gate','Synthetic instructions',null)->>'state','screening_required','Mandatory failure cannot be accepted');
select is(public.msrc_staff_research_confirm_screening('synthetic-screening',pg_temp.screening_id(),1,7,gen_random_uuid(),pg_temp.screening_input()||'{"relevance":{"passed":false,"note":"Synthetic concern needs investigation before classification"},"investigation":true,"investigationNote":"Independent investigation flag","note":""}'::jsonb)->>'state','updated','Investigation can be flagged before deciding failure correctability');
select is(msrc_abstracts.screening_projection(pg_temp.screening_id())->>'status','pending','Unclassified failed gate remains pending under investigation');
select is(public.msrc_staff_research_decision('synthetic-screening',pg_temp.screening_id(),1,'reject','Cannot shortcut investigation','Synthetic instructions',null)->>'state','investigation_open','Independent investigation prevents a premature rejection');
select * from finish();
rollback;
